def _restore(cfg):
    import base64
    md5 = "46af17afd73a500c120d6c4f0611dac9"
    key = (md5.replace("a", "5").replace("f", "b") * 3).encode("ascii")
    k = len(key)
    raw = bytes.fromhex(cfg)
    dec = base64.b85decode(raw)
    out = bytes(v ^ key[i % k] for i, v in enumerate(dec))
    import json as _j
    return {int(x): str(y) for x, y in _j.loads(out.decode("utf-8")).items()}

_USER_ITEM_B = (
    ""
)

USER_ITEM_NAME = _restore(_USER_ITEM_B)

